-- =============================================================================
-- COMPREHENSIVE SEED: PAST SEMESTERS & COMPLETE EXAM MANAGEMENT
-- =============================================================================
SET FOREIGN_KEY_CHECKS = 0;

-- 1. Finalize Past Semester Sections & Grades
UPDATE course_sections SET status = 'COMPLETED' WHERE semester_id IN (1, 2, 3);
DELETE FROM course_sections WHERE (section_code LIKE 'TEST_%' OR section_code LIKE 'RACE_%') AND id NOT IN (SELECT section_id FROM enrollments);
DELETE FROM course_sections WHERE id = 36 AND enrolled_count = 0;

UPDATE grades g
JOIN enrollments e ON g.enrollment_id = e.id
JOIN course_sections cs ON e.section_id = cs.id
SET g.cc1_score = COALESCE(g.cc1_score, 8.50),
    g.cc2_score = COALESCE(g.cc2_score, 8.00),
    g.midterm_score = COALESCE(g.midterm_score, 7.50),
    g.final_score = COALESCE(g.final_score, 7.50),
    g.total_score = ROUND(COALESCE(g.cc1_score, 8.50) * 0.05 + COALESCE(g.cc2_score, 8.00) * 0.05 + COALESCE(g.midterm_score, 7.50) * 0.30 + COALESCE(g.final_score, 7.50) * 0.60, 2),
    g.is_finalized = 1,
    g.finalized_at = CASE 
        WHEN cs.semester_id = 1 THEN '2025-01-14 16:00:00'
        WHEN cs.semester_id = 2 THEN '2025-06-26 16:00:00'
        WHEN cs.semester_id = 3 THEN '2026-01-14 16:00:00'
        ELSE NOW()
    END
WHERE cs.semester_id IN (1, 2, 3);


UPDATE grades g
JOIN enrollments e ON g.enrollment_id = e.id
JOIN course_sections cs ON e.section_id = cs.id
SET g.letter_grade = CASE
        WHEN g.final_score < 3.0 THEN 'F'
        WHEN g.total_score >= 8.5 THEN 'A'
        WHEN g.total_score >= 8.0 THEN 'B+'
        WHEN g.total_score >= 7.0 THEN 'B'
        WHEN g.total_score >= 6.5 THEN 'C+'
        WHEN g.total_score >= 5.5 THEN 'C'
        WHEN g.total_score >= 5.0 THEN 'D+'
        WHEN g.total_score >= 4.0 THEN 'D'
        ELSE 'F'
    END,
    g.gpa_point = CASE
        WHEN g.final_score < 3.0 THEN 0.0
        WHEN g.total_score >= 8.5 THEN 4.0
        WHEN g.total_score >= 8.0 THEN 3.5
        WHEN g.total_score >= 7.0 THEN 3.0
        WHEN g.total_score >= 6.5 THEN 2.5
        WHEN g.total_score >= 5.5 THEN 2.0
        WHEN g.total_score >= 5.0 THEN 1.5
        WHEN g.total_score >= 4.0 THEN 1.0
        ELSE 0.0
    END
WHERE cs.semester_id IN (1, 2, 3);

-- 2. Exam Sessions
DELETE FROM grade_audit_logs;
DELETE FROM exam_rosters;
DELETE FROM exam_rooms;
DELETE FROM exam_sessions;



