-- 5. Student Invoices for Past Semesters

SELECT e.student_id, cs.id, sub.credits, 450000.00, 1.00, sub.credits * 450000.00, 'PAID',
       DATE_ADD(sem.start_date, INTERVAL 20 DAY), 'BANK_TRANSFER',
       CONCAT('BL-', sem.semester_code, '-', e.id), 1, sem.start_date
FROM enrollments e
JOIN course_sections cs ON e.section_id = cs.id
JOIN subjects sub ON cs.subject_id = sub.id
JOIN semesters sem ON cs.semester_id = sem.id
WHERE cs.semester_id IN (1, 2, 3) AND e.status != 'CANCELLED'
  AND NOT EXISTS (
      SELECT 1 FROM student_invoices si WHERE si.student_id = e.student_id AND si.section_id = cs.id
  );


SET FOREIGN_KEY_CHECKS = 1;